593		}
594		if _, err := n2.Candidates(2); reason(err) != ReasonUnknownRound {
595			t.Fatalf("fresh round should have no records, got %v", err)
596		}
597	}
598	
599	// 版本 1 的旧状态目录仍可打开：未决提议与票数作为本地候选恢复，
600	// 过去没有保存的候选详情明确显示无记录，确认块不变。
601	func TestOpenV1State(t *testing.T) {
602		keys := genKeys(t, 4)
603		dir := t.TempDir()
604		vals := make([][]byte, len(keys))
605		for i, k := range keys {
606			vals[i] = k.pub
607		}
