609		if err != nil {
610			t.Fatal(err)
611		}
612		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
613		n.Submit(a1)
614		p, _ := n.Propose()
615		n.Vote(keys[0].pub, 1, p.BlockID)
616	
617		// 把当前状态改写为版本 1 的文件形态：仅 Proposal 字段，没有 Rounds。
618		st := n.st.clone()
619		rs := st.Rounds[1]
620		local := rs.Candidates[rs.LocalBlockID]
621		st.Version = 1
