307	// 重复请求返回同一提议；提议冻结后新交易不改变提议，提议中交易禁止替换。
308	func TestProposalStableAndFrozen(t *testing.T) {
309		keys := genKeys(t, 4)
310		n, _ := newTestNode(t, keys, 10)
311		tx1 := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
312		if _, err := n.Submit(tx1); err != nil {
313			t.Fatal(err)
314		}
315		p1, err := n.Propose()
316		if err != nil {
317			t.Fatal(err)
318		}
319		p2, err := n.Propose()
320		if err != nil {
321			t.Fatal(err)
322		}
323		if p1.BlockID != p2.BlockID || len(p2.TxIDs) != 1 || p2.TxIDs[0] != tx1.ID() {
324			t.Fatal("repeated proposal must be identical")
325		}
326		// 提议后再提交的交易不改变当前提议
327		tx2 := NewTransaction(keys[1].priv, 1, []byte("b"), 99, 100)
328		if _, err := n.Submit(tx2); err != nil {
329			t.Fatal(err)
330		}
331		p3, _ := n.Propose()
332		if len(p3.TxIDs) != 1 {
333			t.Fatalf("proposal changed after new submit: %v", p3.TxIDs)
334		}
335		// 提议中的交易禁止替换
336		replace := NewTransaction(keys[0].priv, 1, []byte("a2"), 999, 100)
337		if _, err := n.Submit(replace); reason(err) != ReasonProposalLocked {
338			t.Fatalf("got %v, want %s", err, ReasonProposalLocked)
339		}
340		info, _ := n.Tx(tx1.ID())
341		if info.Status != StatusProposed {
342			t.Fatalf("tx in proposal status = %s, want proposed", info.Status)
343		}
344		acct := n.Account(keys[0].pub)
345		if len(acct.Pending) != 1 || acct.Pending[0].Status != StatusProposed || acct.Pending[0].Note != "waiting-vote" {
346			t.Fatalf("proposed tx should show waiting-vote: %+v", acct.Pending)
347		}
348		// 未确认时结束轮次，交易回到排队状态
349		r, err := n.EndRound()
350		if err != nil {
351			t.Fatal(err)
352		}
353		if r != 2 {
354			t.Fatalf("round after end = %d, want 2", r)
355		}
356		acct = n.Account(keys[0].pub)
357		if acct.Pending[0].Status != StatusQueued || acct.Pending[0].Note != "waiting-pack" {
358			t.Fatalf("returned tx should be queued/waiting-pack: %+v", acct.Pending[0])
359		}
360		if _, ok := n.Proposal(); ok {
361			t.Fatal("proposal should be cleared after EndRound")
362		}
363		if n.Height() != 0 {
364			t.Fatal("ended round must leave no confirmed block")
365		}
366	}
