// 缩减节点真实的未投票名单。
func TestCandidatesQueryEmptyListAndNoVotesIndependent(t *testing.T) {
	keys := genKeys(t, 4)
	n, _ := newTestNode(t, keys, 10)

	tx := NewTransaction(keys[0].priv, 1, []byte("only"), 5, 100)
